-- 发票权限码追加到内置角色（不改写已应用的角色种子，不碰商家自建角色）。与 BizPerms.ROLE_PERMS 一致。
UPDATE mch_role SET perms=JSON_ARRAY_APPEND(perms,'$','biz:invoice:read'),updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE entity_no='*' AND builtin=1 AND role_code='MANAGER' AND deleted=0 AND JSON_CONTAINS(perms,JSON_QUOTE('biz:invoice:read'))=0;
UPDATE mch_role SET perms=JSON_ARRAY_APPEND(perms,'$','biz:invoice:issue'),updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE entity_no='*' AND builtin=1 AND role_code='MANAGER' AND deleted=0 AND JSON_CONTAINS(perms,JSON_QUOTE('biz:invoice:issue'))=0;
UPDATE mch_role SET perms=JSON_ARRAY_APPEND(perms,'$','biz:invoice:void'),updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE entity_no='*' AND builtin=1 AND role_code='MANAGER' AND deleted=0 AND JSON_CONTAINS(perms,JSON_QUOTE('biz:invoice:void'))=0;
UPDATE mch_role SET perms=JSON_ARRAY_APPEND(perms,'$','biz:invoice:setup'),updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE entity_no='*' AND builtin=1 AND role_code='MANAGER' AND deleted=0 AND JSON_CONTAINS(perms,JSON_QUOTE('biz:invoice:setup'))=0;
UPDATE mch_role SET perms=JSON_ARRAY_APPEND(perms,'$','biz:invoice:read'),updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE entity_no='*' AND builtin=1 AND role_code='CLERK' AND deleted=0 AND JSON_CONTAINS(perms,JSON_QUOTE('biz:invoice:read'))=0;
UPDATE mch_role SET perms=JSON_ARRAY_APPEND(perms,'$','biz:invoice:issue'),updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE entity_no='*' AND builtin=1 AND role_code='CLERK' AND deleted=0 AND JSON_CONTAINS(perms,JSON_QUOTE('biz:invoice:issue'))=0;
